import { Suspense } from 'react'
import { notFound } from 'next/navigation'
import { getProduct, getRelatedProducts } from '@/lib/products'

type Props = {
  params: Promise<{ slug: string }>
  searchParams: Promise<{ currency?: string | string[] }>
}

export default function ProductPage({ params, searchParams }: Props) {
  return (
    <main>
      <p>Signal Shop collection</p>
      <Suspense fallback={<ProductDetailsFallback />}>
        <ProductDetails params={params} searchParams={searchParams} />
      </Suspense>
    </main>
  )
}

async function ProductDetails({ params, searchParams }: Props) {
  const { slug } = await params
  const { currency: rawCurrency } = await searchParams
  const currency = (Array.isArray(rawCurrency) ? rawCurrency[0] : rawCurrency) || 'USD'
  const product = await getProduct(slug, currency)
  if (!product) notFound()

  return (
    <>
      <h1>{product.name}</h1>
      <p>{product.price}</p>
      <section>
        <h2>Related products</h2>
        <Suspense fallback={<p>Loading related products…</p>}>
          <RelatedProducts slug={slug} />
        </Suspense>
      </section>
    </>
  )
}

async function RelatedProducts({ slug }: { slug: string }) {
  const related = await getRelatedProducts(slug)
  return related.map((item) => <p key={item.slug}>{item.name}</p>)
}

function ProductDetailsFallback() {
  return (
    <>
      <h1>Loading product…</h1>
      <p>Loading price…</p>
    </>
  )
}
